#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long maxPower(vector<int>& stations,int r,int k){
  int n=stations.size();vector<long long> pre(n+1);
  for(int i=0;i<n;++i)pre[i+1]=pre[i]+stations[i];
  vector<long long> base(n);
  for(int i=0;i<n;++i)base[i]=pre[min(n,i+r+1)]-pre[max(0,i-r)];
  auto feasible=[&](long long target){
   vector<long long> expire(n+1,0);long long active=0,used=0;
   for(int i=0;i<n;++i){
    active+=expire[i];long long need=max(0LL,target-base[i]-active);
    used+=need;if(used>k)return false;
    active+=need;int end=min(n,i+2*r+1);expire[end]-=need;
   }
   return true;
  };
  long long lo=*min_element(base.begin(),base.end()),hi=*max_element(base.begin(),base.end())+k;
  while(lo<hi){long long mid=lo+(hi-lo+1)/2;if(feasible(mid))lo=mid;else hi=mid-1;}
  return lo;
 }
};
